// swift-tools-version: 6.2
// Nimbra's mail engine (Rust, crates/nimbra-ffi) as a Swift package: the static libraries
// in NimbraFFI.xcframework, and the Swift API UniFFI generates over them
// (Sources/NimbraCore, generated by scripts/build-ios-core.sh, never edited by hand).
//
// A checkout with a local build (`scripts/build-ios-core.sh`) uses that XCFramework.
// Otherwise the package takes the one attached to the release below, by URL and checksum:
// `scripts/build-ios-core.sh --release-zip` makes the zip and prints both.
import Foundation
import PackageDescription

/// The release the package points at when there is no local build.
let releaseURL = "https://github.com/nimbra-mail/core/releases/download/v0.1.7/NimbraFFI.xcframework.zip"
let releaseChecksum = "b668143987665c730cad871288237668c9de0bc25c957352e49cd9a664c7e0ff"

let packageDir = URL(fileURLWithPath: #filePath).deletingLastPathComponent().path
let localBuild = FileManager.default.fileExists(atPath: "\(packageDir)/NimbraFFI.xcframework")

let engine: Target
if localBuild {
    engine = .binaryTarget(name: "NimbraFFI", path: "NimbraFFI.xcframework")
} else if !releaseURL.isEmpty {
    engine = .binaryTarget(name: "NimbraFFI", url: releaseURL, checksum: releaseChecksum)
} else {
    fatalError("No NimbraFFI.xcframework: run scripts/build-ios-core.sh in this package first.")
}

let package = Package(
    name: "NimbraCore",
    platforms: [.iOS(.v26)],
    products: [
        .library(name: "NimbraCore", targets: ["NimbraCore"]),
    ],
    targets: [
        engine,
        .target(
            name: "NimbraCore",
            dependencies: ["NimbraFFI"],
            linkerSettings: [
                // The Keychain (keyring, through security-framework).
                .linkedFramework("Security"),
                .linkedFramework("CoreFoundation"),
            ]
        ),
    ]
)
